export function registryDemoCases(
  registry: RegistryName,
): readonly { name: string; request: RegistryRequest }[] {
  return FIXTURES.map((item) => ({
    name: item.name,
    request: snapshotRegistryRequest(JSON.parse(item.raw).request),
  })).filter((item) => item.request.registry === registry);
}

export function registryDemoResponse(
  request: RegistryRequest,
  scenario: string,
): RegistryResponse {
  const expected = snapshotRegistryRequest(request);
  for (const item of FIXTURES) {
    if (item.name !== scenario) continue;
    try {
      return parseRegistryResponse(item.raw, expected);
    } catch {
      /* Try another independently generated example. */
    }
  }
  throw new Error("Select an available synthetic registry example.");
}
